<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to rewrite:
<original_code>
#include<iostream>
#include<cstdio>
#include<cstdlib>
#include<cstring>
#include<algorithm>
#include<cmath>
#include<queue>
#include<set>
#include<stack>
#include<map>
#include<vector>
#include<bitset>
#define fi first
#define se second
#define pb push_back
#define mk make_pair
using namespace std;
typedef long long ll;
typedef unsigned long long ull;
ll read()
{
    char ch=getchar();ll x=0,f=1;
    while(ch<'0'||ch>'9')
    {
        if(ch=='-') f=-1;
        ch=getchar();
    }
    x=ch-'0';
    while(1)
    {
        ch=getchar();
        if(ch<'0'||ch>'9') break;
        x=x*10+ch-'0';
    }
    return x*f;
}
const ll mod=1e9+7;
ll p,k,ret;
ll qmul(ll a,ll b,ll Mod)
{
    ll ans=0;
    while(b)
    {
        if(b&1) ans=(ans+a)%Mod;
        b>>=1;a=(a+a)%Mod;
    }
    return ans;
}
ll qpow(ll a,ll b,ll Mod)
{
    ll ans=1;
    while(b)
    {
        if(b&1) ans=qmul(ans,a,Mod);
        b>>=1;a=qmul(a,a,Mod);
    }
    return ans;
}
int main()
{
  //  freopen("B.in","r",stdin);
   // freopen("B.out","w",stdout);
    p=read(),k=read();
    if(k==0) ret=qpow(p,p-1,mod);
    if(k==1) ret=qpow(p,p,mod);
    if(k>1)
    {
        ll l=1,cur=k;
        while(cur!=1)
        {
            cur=(ll) cur*k%p;
            l++;
        }
        ret=qpow(p,(p-1)/l,mod);
    }
    printf("%I64d\n",ret);
  //  fclose(stdin);
  //  fclose(stdout);
    return 0;
}

